import{a as e}from"./chunk-2JSIA3BV.js";import{a}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var r=a(e,["Elige d\xF3nde se guarda tu trabajo","\xBFYa tienes una carpeta de Grading Studio? El\xEDgela y tu trabajo vuelve.","Ahora no","La barra lateral seguir\xE1 diciendo “Sin copia de seguridad” hasta que elijas una carpeta. Haz clic ah\xED cuando quieras.","Tu trabajo no tiene copia de seguridad","Crear un archivo para llevar","Ahora mismo tus correcciones solo est\xE1n en este navegador, y borrar los datos del navegador las eliminar\xEDa. Elige una carpeta de este ordenador una vez. Cada guardado ir\xE1 tambi\xE9n all\xED, con una copia de cada d\xEDa a la que volver. No se sube nada.","El trabajo cambi\xF3 en otra ventana mientras esto estaba abierto, as\xED que hay algo nuevo que elegir. A\xFAn no se ha tra\xEDdo nada.","Esto cambi\xF3 tanto aqu\xED como en el archivo. Elige lo que quieres en cada caso.","Los comentarios guardados del otro ordenador se a\xF1aden a los tuyos","Trayendo tu trabajo…","Cambios en descargas que tienes aqu\xED",{one:"Un estudiante llega desde el archivo",other:"{n} estudiantes llegan desde el archivo"},{one:"Un ejemplo llega o cambia",other:"{n} ejemplos llegan o cambian"},{one:"Cambia un archivo: archivos con retraso, lecturas o ediciones de Word",other:"Cambian {n} archivos: archivos con retraso, lecturas o ediciones de Word"},"No termin\xF3. Tu trabajo est\xE1 a salvo, y antes se hizo una copia de protecci\xF3n: Restaurar est\xE1 abajo si algo no se ve bien.","En el archivo","Este navegador se qued\xF3 sin espacio, as\xED que no termin\xF3. Tus marcas y notas de aqu\xED no se reemplazaron. Libera espacio en el disco y vuelve a intentarlo.","Traerlo","Olvidada","Olvidada en el otro ordenador, as\xED que tambi\xE9n se quita aqu\xED","Sigue olvidada",{one:"Un cambio en clases, unidades o listas",other:"{n} cambios en clases, unidades o listas"},"Creado {when}",{one:"Una descarga nueva",other:"{n} descargas nuevas"},"Nada que traer: lo que hay aqu\xED ya tiene todo lo de este archivo.","R\xFAbricas o ajustes que a\xFAn no tienes aqu\xED",{one:"Una lecci\xF3n, archivo o ajuste que tu planificaci\xF3n de aqu\xED no tiene",other:"{n} lecciones, archivos o ajustes que tu planificaci\xF3n de aqu\xED no tiene"},"Llega tu planificaci\xF3n, con sus unidades, horario y archivos. Vuelve a vincular su carpeta si usas una.","Puede que este navegador no tenga espacio: necesita unos {need} y tiene unos {room}.","Antes se hace una copia de protecci\xF3n de c\xF3mo est\xE1 todo ahora, as\xED que puedes deshacerlo abajo.",{one:"Una descarga no tiene nada que traer.",other:"{n} descargas no tienen nada que traer."},"Recursos del centro a\xF1adidos o cambiados en el otro ordenador",{one:"Un ajuste llega desde el archivo",other:"{n} ajustes llegan desde el archivo"},"El peque\xF1o almac\xE9n de este navegador para listas y ajustes est\xE1 lleno, as\xED que no termin\xF3. Tus marcas y notas de aqu\xED no se reemplazaron.",{one:"Un estudiante sigue igual aqu\xED, porque esta copia es m\xE1s reciente",other:"{n} estudiantes siguen igual aqu\xED, porque esta copia es m\xE1s reciente"},{one:"un estudiante",other:"{n} estudiantes"},"Exportar lo que tengo","El navegador no quiso guardarlas, a menudo porque el equipo no tiene espacio. Deje esta ventana abierta, libere algo de espacio y pulse Intentar de nuevo.","Sus \xFAltimas marcas y puntuaciones NO est\xE1n guardadas.","Guardado. Su trabajo vuelve a estar a salvo.","Sus \xFAltimas marcas y puntuaciones solo est\xE1n guardadas en parte, en la peque\xF1a copia r\xE1pida de este navegador.","Intentar de nuevo","Traer trabajo","Escribe la frase de contrase\xF1a de {name}. Se comprueba todo el archivo antes de cambiar nada aqu\xED.","\xBFCorriges en otro ordenador o te cambias a uno nuevo? Crea aqu\xED un archivo para llevar y tr\xE1elo all\xED. Lo mismo para la vuelta.","Llevar tu trabajo","Esto es el ejemplo, as\xED que a\xFAn no hay nada tuyo que llevar.","Un archivo","Un estudiante (la correcci\xF3n an\xF3nima est\xE1 activada)","Recuperarla","Cambiado {when}","Primero elige una versi\xF3n para cada uno.","en un momento anterior","Sin nota, comentario ni marcas",{one:"{file}: una marca",other:"{file}: {n} marcas"},"En tu carpeta","{file} va a {key}","Esta descarga se olvid\xF3, pero una copia tiene trabajo posterior.","En este ordenador","No coinciden en este navegador y en tu carpeta, as\xED que no se eligi\xF3 nada por ti. Hasta que decidas, cada sitio conserva la suya.","Decidir despu\xE9s","Dejarla olvidada","Corregido {v}","Elegir la m\xE1s reciente en cada caso","Sin clase","Nada configurado","Nada aqu\xED","Desactivado","Usar lo que eleg\xED","Activado","Un archivo va a un estudiante","Puntos: {v}","Puntos, sobre {n}","Estas dos copias no tienen las mismas filas de r\xFAbrica, as\xED que cada una muestra las suyas.","R\xFAbrica: {list}",{one:"R\xFAbrica con una fila",other:"R\xFAbrica con {n} filas"},"Las notas se guardan en ambos casos. Los totales y porcentajes siguen la que elijas.","Hoja de notas: {v}","Dos versiones para elegir","Comprobando el archivo…","Comprobando el archivo… {n} de {of}","Cerrar","Decidir","Hecho","Unidades compartidas","\xDAltima carpeta","Mi unidad","Compartido conmigo","Este archivo est\xE1 da\xF1ado o se ha cambiado desde que se cre\xF3, as\xED que no es fiable. Aqu\xED no ha cambiado nada. Crea uno nuevo si puedes.","Este archivo se cre\xF3 con una versi\xF3n m\xE1s nueva de Grading Studio. Aqu\xED no ha cambiado nada. Recarga esta p\xE1gina para obtener la versi\xF3n m\xE1s nueva y vuelve a intentarlo.","Esa no es una copia de seguridad de Grading Studio.","Ese no es un archivo para llevar de Grading Studio.","Esa frase de contrase\xF1a no abre este archivo. Rev\xEDsala e int\xE9ntalo de nuevo. Si est\xE1s seguro de ella, puede que el archivo est\xE9 da\xF1ado. Aqu\xED no ha cambiado nada.","Elige una vez una carpeta en este ordenador, y cada guardado ir\xE1 all\xED adem\xE1s de a este navegador, con una copia de cada d\xEDa a la que volver. Elige algo privado: guarda trabajos de estudiantes. Cuando Chrome pregunte, elige \xABPermitir en todas las visitas\xBB. Si ya tienes una carpeta de Grading Studio, el\xEDgela y tu trabajo vuelve.","Todo se recuper\xF3 desde tu carpeta.","No se pudo usar esa carpeta. Prueba con otra.",{one:"Lleg\xF3 trabajo m\xE1s reciente desde tu carpeta para un estudiante.",other:"Lleg\xF3 trabajo m\xE1s reciente desde tu carpeta para {n} estudiantes."},"Elegir una carpeta…","Hecho. Tu trabajo ahora tambi\xE9n se guarda en “{name}”.","Est\xE1 en una carpeta llamada \xAB{root}\xBB dentro de \xAB{name}\xBB.","Aqu\xED se guarda una copia de tus trabajos, marcas, notas, comentarios, listas y r\xFAbricas, sin ning\xFAn bot\xF3n de guardar que recordar. Si alguna vez se borra este navegador, vuelve a vincular la carpeta y todo regresa.","Algunos archivos que tu carpeta indica ya no est\xE1n o est\xE1n da\xF1ados, as\xED que no se pudieron recuperar. Afecta a: {list}. Tus marcas, notas y comentarios est\xE1n todos aqu\xED. Para recuperar los trabajos, vuelve a soltar la misma descarga.","Usar otra carpeta…","Lleg\xF3 trabajo m\xE1s reciente desde tu carpeta, as\xED que esta descarga se ha vuelto a abrir.","Dejar de usar esta carpeta","Dejar de usarla","\xBFDejar de guardar en \xAB{name}\xBB?","Lo que ya est\xE1 en la carpeta se queda all\xED. No se elimina nada. Tu trabajo sigue en este navegador, sin una segunda copia.","Ya no se guarda en una carpeta. Los archivos de la carpeta siguen ah\xED.","Para que todo vuelva a como estaba entonces:","Una tarea","No se pudo leer esa copia. Si tu carpeta est\xE1 en una unidad desconectada, con\xE9ctala e int\xE9ntalo de nuevo.",{one:"el trabajo de {n} estudiante es distinto",other:"el trabajo de {n} estudiantes es distinto"},"\xAB{name}\xBB ha vuelto a como estaba el {when}.","No termin\xF3, as\xED que no se restaur\xF3 nada.","C\xF3mo estaba cada tarea el {when}:","Ver","{n} puntuadas","Ninguna de las tareas que hay ahora en este navegador estaba en esta copia.","{n} de {of} puntuadas","Restaurar esta tarea","Leyendo esta copia…","Este ordenador no tiene espacio, as\xED que no se restaur\xF3 nada.","Igual entonces que ahora","su configuraci\xF3n es distinta","Entonces {then}, ahora {now}","No se pudo deshacer aqu\xED. La copia hecha justo antes de restaurar est\xE1 en esta p\xE1gina.","Deshecho. \xAB{name}\xBB est\xE1 como antes.","La carpeta guarda una copia de cada d\xEDa, y otra antes de cualquier cambio grande. Volver atr\xE1s deja tus marcas, notas, comentarios, archivos con retraso, lecturas, listas y ajustes como estaban entonces. Los trabajos se quedan.","Copia del d\xEDa","No termin\xF3. Puede que tu trabajo se haya recuperado en parte: usa Restaurar en la copia de protecci\xF3n m\xE1s reciente, abajo.","Volver","Volver atr\xE1s en el tiempo","Vincula una carpeta y guardar\xE1 una copia de cada d\xEDa a la que volver.","A\xFAn no hay copias en la carpeta. La primera se hace hoy.","\xBFVolver a esta copia del {when}?","Tus marcas, notas, comentarios, archivos con retraso, lecturas, listas y ajustes vuelven a como estaban entonces, en este navegador y en la carpeta. Los trabajos se quedan. Antes se hace una copia de c\xF3mo est\xE1 todo ahora, as\xED que se puede deshacer.","Abrirlo","Empaquetando tu trabajo…","Empaquetando tu trabajo… {n} de unos {of}","Correcci\xF3n an\xF3nima","Avisos en archivos nuevos y cambiados","Fragmentos de v\xEDdeo","Clase","Enlace de Google Drive","Trabajo en grupo","Iluminaci\xF3n","Archivos movidos","Un ajuste","Casillas de correcci\xF3n r\xE1pida","Qu\xE9 lecturas ve cada estudiante","Archivos quitados y reemplazados","Devuelto a los estudiantes","Tus respuestas sobre p\xE1ginas escaneadas","Configurar r\xFAbrica","Recuadros para tapar y c\xF3digos para compartir","V\xEDdeos girados a la posici\xF3n correcta","Frase de contrase\xF1a","Otra vez, para asegurarte","Elige una frase de contrase\xF1a de unas pocas palabras. Si la olvidas, nadie podr\xE1 abrir este archivo, ni siquiera t\xFA, pero tu trabajo aqu\xED no se ve afectado. Aun as\xED, guarda el archivo en un lugar privado.","No coinciden.","Usa al menos 8 caracteres. Unas cuantas palabras normales funcionan bien.","Volver a conectar","Hecho. Recargando…","Quitar de este ordenador","Tu \xFAltimo archivo para llevar se cre\xF3 {when}, despu\xE9s de tu \xFAltimo cambio.","Quitado de este ordenador. Recargando…","No se pudo quitar todo. Cierra las dem\xE1s ventanas de Grading Studio y vuelve a intentarlo.","Tu carpeta vinculada “{name}” no se toca: sus archivos se quedan donde est\xE1n, y este navegador deja de guardar en ella.","Conservarlo","No has creado ning\xFAn archivo para llevar desde este navegador, as\xED que lo hecho aqu\xED puede no estar en ning\xFAn otro sitio.",{one:"Una descarga tiene cambios desde tu \xFAltimo archivo para llevar ({when}). Esos cambios no est\xE1n en ese archivo.",other:"{n} descargas tienen cambios desde tu \xFAltimo archivo para llevar ({when}). Esos cambios no est\xE1n en ese archivo."},"La planificaci\xF3n no se toca. Esto no se puede deshacer.",{one:"Esto quita todo el trabajo de los estudiantes de este navegador: una descarga con sus trabajos, marcas, notas y comentarios, adem\xE1s de listas, unidades, r\xFAbricas, archivos con retraso, lecturas, ediciones de Word, recursos del centro, ejemplos y copias de protecci\xF3n.",other:"Esto quita todo el trabajo de los estudiantes de este navegador: {n} descargas con sus trabajos, marcas, notas y comentarios, adem\xE1s de listas, unidades, r\xFAbricas, archivos con retraso, lecturas, ediciones de Word, recursos del centro, ejemplos y copias de protecci\xF3n."},"Escribe QUITAR para continuar","QUITAR","Antes de cualquier cosa arriesgada, como traer trabajo, volver atr\xE1s en el tiempo o empezar un curso nuevo, se guarda en este navegador una copia completa de tu trabajo. Se conservan las tres m\xE1s recientes. Los trabajos no van en ellas, porque nunca cambian.","Hecha por la versi\xF3n actual de la app","Copias de protecci\xF3n","A\xFAn no hay copias de protecci\xF3n.","Restaurar","\xBFRestaurar la copia de protecci\xF3n del {when}?","Todo vuelve a como estaba entonces, y lo a\xF1adido despu\xE9s desaparece. Los trabajos se quedan, as\xED que una descarga abierta despu\xE9s conserva su fila sin marcas. Antes se guarda c\xF3mo est\xE1 todo ahora, as\xED que se puede deshacer.","Detener","Llevarme mi trabajo","Crea un archivo protegido con todo lo necesario para corregir en otro ordenador: archivos de los estudiantes, marcas, notas, comentarios, listas, r\xFAbricas, lecturas, ediciones de Word, archivos a\xF1adidos y buenos ejemplos. Tu planificaci\xF3n tambi\xE9n va: lecciones, unidades, horario y sus archivos.","Hecho: {name} ({size}). Abre Grading Studio en el otro ordenador y usa Traer trabajo. Lo mismo para la vuelta.","Sus trabajos no est\xE1n en el archivo para: {list}. Solo fueron las marcas y las notas. Necesitar\xE1s esas descargas en el otro ordenador.","El archivo no termin\xF3, as\xED que no sirve. Tu trabajo aqu\xED est\xE1 bien. Int\xE9ntalo de nuevo en un sitio con m\xE1s espacio.","Trabajo de Grading Studio {day}","Crear el archivo","Trabajo de Grading Studio","No hay trabajos de: {list}. Este navegador no los guarda, as\xED que en el archivo solo ir\xE1n las marcas y las notas. Para llevar tambi\xE9n los trabajos, suelta aqu\xED antes cada una de esas descargas.","No se pudo escribir el archivo ah\xED. Prueba en otro sitio.","Solo en este navegador. \xAB{name}\xBB necesita un clic para volver a conectarse","Chrome necesita tu permiso para volver a usar la carpeta. Elige \xABPermitir en todas las visitas\xBB y no volver\xE1 a preguntar","Comprobando d\xF3nde se guarda tu trabajo…",{one:"Una cosa que decidir sobre tu carpeta",other:"{n} cosas que decidir sobre tu carpeta"},"Dos versiones entre las que elegir","Copia de seguridad en tu Google Drive","Cada cambio tambi\xE9n va a la carpeta oculta de Grading Studio en tu Google Drive","Solo en este navegador. El disco de “{name}” est\xE1 lleno","{text}.","{text}. {tip}.","Solo en este navegador. No se puede acceder a “{name}”","Se pondr\xE1 al d\xEDa sola en cuanto vuelva la carpeta","Sin copia de seguridad. Solo en este navegador","Borrar los datos de este navegador borrar\xEDa tu trabajo. Este navegador no puede guardar en una carpeta, as\xED que crea un archivo para llevar cuando termines de corregir","Si se borran los datos de este navegador, se borrar\xEDa tu trabajo. Elige una carpeta y cada guardado ir\xE1 tambi\xE9n all\xED","En este navegador y en tu carpeta “{name}”","Cada guardado va a los dos sitios. \xDAltimo guardado en la carpeta a las {time}","Cada guardado va a los dos sitios","Solo en este navegador. El navegador se qued\xF3 sin espacio y “{name}” no puede ponerse al d\xEDa","Ejemplo, se guarda solo mientras lo exploras","Nada de esto es tu trabajo. Sal del ejemplo y se borra","Guardando en tu carpeta “{name}”…","Guardando en tu carpeta “{name}” ({prog})…","Tu trabajo ya est\xE1 en este navegador","D\xF3nde se guarda tu trabajo","el curso del archivo","Tus clases siguen en un curso nuevo con las listas de clase vac\xEDas. Primero, todo lo de este curso va a un archivo protegido, y el archivo se comprueba antes de borrar nada aqu\xED.","Archivados: {list}",{one:"Una clase, con sus unidades y tarjetas de tarea. Cada tarjeta conserva su r\xFAbrica y sus casillas de correcci\xF3n r\xE1pida. Sin trabajos, notas ni comentarios.",other:"{n} clases, con sus unidades y tarjetas de tarea. Cada tarjeta conserva su r\xFAbrica y sus casillas de correcci\xF3n r\xE1pida. Sin trabajos, notas ni comentarios."},"Qu\xE9 se conserva","El archivo no se ley\xF3 igual que tu trabajo aqu\xED, as\xED que no es fiable. Aqu\xED no se cambi\xF3 nada. Int\xE9ntalo de nuevo en un sitio con m\xE1s espacio.","Fechas de entrega y de periodos, un a\xF1o despu\xE9s","El archivo no termin\xF3, as\xED que aqu\xED no se cambi\xF3 nada. Int\xE9ntalo de nuevo en un sitio con m\xE1s espacio.","El curso que cierras","Guardar el archivo y empezar el curso nuevo","(seg\xFAn las fechas de tus periodos)","Curso escolar","{year} en {file}, {when}","Curso de Grading Studio",{one:"Un conjunto de trabajos va al archivo y sale de este navegador.",other:"{n} conjuntos de trabajos van al archivo y salen de este navegador."},"Ponle nombre a los dos cursos, como 2025–26 y 2026–27.","Este curso: {year}","Abrir un curso archivado","No termin\xF3. {now} est\xE1 a salvo en {file}, y antes se hizo una copia de protecci\xF3n: Restaurar est\xE1 abajo. Recarga antes de hacer nada m\xE1s.","Abrirlo pone ese curso en lugar de lo que hay ahora. Primero, {now} se guarda en su propio archivo con la misma frase de contrase\xF1a, y se comprueba, para que puedas volver de la misma manera.","Este navegador deja de guardar en la carpeta “{name}”, que conserva el curso actual.","Guardar {now} y abrir {year}","Abrir {year}","La planificaci\xF3n no cambia: las lecciones del curso anterior ya est\xE1n en Lecciones anteriores.",{one:"El archivo contiene un conjunto de trabajos, con sus clases, listas de clase, marcas y notas, creado {when}.",other:"El archivo contiene {n} conjuntos de trabajos, con sus clases, listas de clase, marcas y notas, creado {when}."},"Elige una frase de contrase\xF1a de unas pocas palabras. Nadie puede abrir el archivo sin ella, ni siquiera t\xFA, as\xED que ap\xFAntala en un lugar seguro.","Unidades de planificaci\xF3n y el semestre, un a\xF1o despu\xE9s. Las lecciones de este curso pasan a Lecciones anteriores, listas para reutilizar.","Proteger el archivo","Listas de clase, solo para las clases que mantienen los mismos estudiantes. Si no, quedan vac\xEDas y la lista de seguimiento se borra.","El curso nuevo necesita un nombre distinto del que cierras.","Guardando {year} en un archivo…","Empezar un nuevo curso escolar","El curso nuevo no termin\xF3 de configurarse. Todo lo de {year} est\xE1 a salvo en {file}, y antes se hizo una copia de protecci\xF3n: Restaurar est\xE1 abajo si algo no se ve bien.","{year} ha empezado","Tus clases, unidades y tarjetas de tarea est\xE1n listas. Pega los estudiantes de cada clase en su pesta\xF1a Estudiantes si las listas est\xE1n vac\xEDas. Todo lo de {from} est\xE1 en {file} ({size}), comprobado. Gu\xE1rdalo en un lugar seguro con su frase de contrase\xF1a. Abrir un curso archivado lo recupera.","Empezando {year}…","Tus ajustes, escala de notas, r\xFAbricas guardadas y banco de comentarios se quedan como est\xE1n.","El curso nuevo"],null);export{r as default};
